	var TownLoader = class TownLoader {
		static {
			this.townCache = null;
		}
		static ensureCache() {
			if (!TownLoader.townCache) {
				TownLoader.townCache = new Map();
				for (const [id, data] of Object.entries(towns_default)) {
					const town = new Town(id, data.name, data.description, new Coordinate(data.coordinate[0], data.coordinate[1]), data.image, data.specialWeapons, data.specialArmors, data.specialAccessories);
					TownLoader.townCache.set(id, town);
				}
			}
			return TownLoader.townCache;
		}
		static load(s) {
			if (!s) return null;
			const cache = TownLoader.ensureCache();
			if (s instanceof Coordinate) {
				for (const town of cache.values()) if (town.coordinate.equals(s)) return town;
				return null;
			}
			const id = typeof s === "number" ? s.toString() : s;
			const town = cache.get(id);
			if (town) return town;
			for (const t of cache.values()) if (id.startsWith(t.name)) return t;
			return null;
		}
		static getTownList() {
			return Array.from(TownLoader.ensureCache().values());
		}
	};
