	var EventBoardModule = class extends BaseModule {
		_container() {
			return $("#" + this.containerId);
		}
		constructor(credential) {
			super(credential);
			this.containerId = "_EventBoardModule_" + RandomUtils.nextObjectID();
			this._events = [];
			this.conversationLoader = new ConversationLoader(credential);
		}
		generateHTML() {
			return `
<section id='${this.containerId}' class='d-flex flex-column gap-0-5 bg-secondary rounded overflow-hidden'>
    <header class='bg-navy text-yellowgreen d-flex align-items-center justify-content-start px-2 py-1 fw-bold'>
        <i class='bi bi-megaphone me-2'></i>
        <span>最近发生的事件</span>
    </header>
    <div class='flex-grow-1 bg-beige'>
        <div class='p-2 bg-light'>
            <ul class='mb-0 ps-3 C_EBM_EventList'></ul>
        </div>
    </div>
</section>
        `.trim();
		}
		async reload(options) {
			if (options?.conversationLoader) await this.conversationLoader.adopt(options.conversationLoader);
			else this.conversationLoader.reset();
			this._events.length = 0;
			const conversationPage = await this.conversationLoader.loadPage();
			if (conversationPage.events) this._events.push(...conversationPage.events);
		}
		async render() {
			const html = this._events.map((event) => `<li class='py-1 border-bottom'>${event}</li>`).join("");
			this._container().find(".C_EBM_EventList").html(html);
		}
	};
