	var PlayerNpc = class {
		constructor(data) {
			this.name = data.name;
			this.avatarUrl = PocketConfigLoader.application.domain + data.avatarUrl;
		}
		async getImageHtml() {
			return `<img src="${await ImageCacheHelper.getImageUrl(this.avatarUrl)}" width="64" height="64" alt="${this.name}" class="rounded" style="border-width:0">`;
		}
	};
	var TaskNpc = class {
		constructor(data) {
			this.name = data.name;
			this.category = data.category;
			this.avatarUrl = PocketConfigLoader.application.domain + data.avatarUrl;
			this.mapLocation = data.mapLocation;
			this.description = data.description;
		}
		async getImageUrl() {
			return await ImageCacheHelper.getImageUrl(this.avatarUrl);
		}
		async getImageHtml() {
			return `<img src="${await this.getImageUrl()}" width="64" height="64" alt="${this.name}" class="rounded" style="border-width:0">`;
		}
		getDisplayName() {
			return `${this.category} ${this.name}`;
		}
		hasMapLocation() {
			return this.mapLocation !== void 0;
		}
		getMapLocationText() {
			if (this.mapLocation) return `(${this.mapLocation.x}, ${this.mapLocation.y})`;
			return "无位置信息";
		}
	};
	var ZodiacNpc = class {
		constructor(data) {
			this.name = data.name;
			this.nameEn = data.nameEn;
			this.palace = data.palace;
			this.palaceEn = data.palaceEn;
			this.palaceIndex = data.palaceIndex;
			this.title = data.title;
			this.titleEn = data.titleEn;
			this.avatarUrl = PocketConfigLoader.application.domain + data.avatarUrl;
			this.width = data.width;
			this.height = data.height;
			this.description = data.description;
		}
		getAvatarUrl() {
			return this.avatarUrl;
		}
		getAvatarImageHtml(width, height, className) {
			const w = width ?? this.width;
			const h = height ?? this.height;
			const classAttr = className ? ` class="${className}"` : "";
			return `<img src="${this.avatarUrl}" width="${w}" height="${h}" alt="${this.name}"${classAttr} style="border-width:0">`;
		}
		getDisplayName() {
			return `${this.palace} ${this.name}`;
		}
		getFullTitle() {
			return `${this.title} ${this.name}`;
		}
	};
	var NpcProfile = class {
		constructor(data) {
			this.name = data.name;
			this.nameEn = data.nameEn;
			this.profession = data.profession;
			this.professionEn = data.professionEn;
			this.gender = data.gender;
			this.description = data.description;
			this.avatarUrl = data.avatarUrl ? PocketConfigLoader.application.domain + data.avatarUrl : void 0;
			this.greetings = data.greetings;
		}
		getRandomGreeting() {
			if (!this.greetings || this.greetings.length === 0) return `${this.name}向你致意。`;
			return RandomUtils.randomElement(this.greetings);
		}
		async getImageUrl() {
			return ImageCacheHelper.getImageUrl(this.avatarUrl);
		}
		async getImageHtml() {
			return `<img src="${await this.getImageUrl()}" width="64" height="64" alt="${this.name}" class="rounded" style="border-width:0">`;
		}
		getDisplayName() {
			return `${this.name}（${this.profession}）`;
		}
	};
	var NpcProfileLoader = class {
		static getRandomProfile() {
			const entries = Object.entries(npc_profiles_default.npcs);
			const [, data] = RandomUtils.randomElement(entries);
			return new NpcProfile(data);
		}
		static getAllProfiles() {
			return Object.entries(npc_profiles_default.npcs).map(([, data]) => new NpcProfile(data));
		}
		static getProfilesByGender(gender) {
			return this.getAllProfiles().filter((profile) => profile.gender === gender);
		}
		static getPlayerNpcByName(name) {
			const playerNpcsData = npc_profiles_default.playerNpcs;
			if (!playerNpcsData) return null;
			const data = playerNpcsData[name];
			if (!data) return null;
			return new PlayerNpc(data);
		}
		static getAllPlayerNpcs() {
			const playerNpcsData = npc_profiles_default.playerNpcs;
			if (!playerNpcsData) return [];
			return Object.entries(playerNpcsData).map(([, data]) => new PlayerNpc(data));
		}
		static getZodiacNpcByName(name) {
			const zodiacNpcsData = npc_profiles_default.zodiacNpcs;
			if (!zodiacNpcsData) return null;
			const data = zodiacNpcsData[name];
			if (!data) return null;
			return new ZodiacNpc(data);
		}
		static getZodiacNpcByPalaceIndex(palaceIndex) {
			if (palaceIndex < 1 || palaceIndex > 12) return null;
			return this.getAllZodiacNpcs().find((npc) => npc.palaceIndex === palaceIndex) ?? null;
		}
		static getAllZodiacNpcs() {
			const zodiacNpcsData = npc_profiles_default.zodiacNpcs;
			if (!zodiacNpcsData) return [];
			return Object.entries(zodiacNpcsData).map(([, data]) => new ZodiacNpc(data)).sort((a, b) => a.palaceIndex - b.palaceIndex);
		}
		static getZodiacNpcNames() {
			return this.getAllZodiacNpcs().map((npc) => npc.name);
		}
		static getTaskNpcByName(name) {
			const taskNpcsData = npc_profiles_default.taskNpcs;
			if (!taskNpcsData) return null;
			const data = taskNpcsData[name];
			if (!data) return null;
			return new TaskNpc(data);
		}
		static getAllTaskNpcs() {
			const taskNpcsData = npc_profiles_default.taskNpcs;
			if (!taskNpcsData) return [];
			return Object.entries(taskNpcsData).map(([, data]) => new TaskNpc(data));
		}
		static getTaskNpcsByCategory(category) {
			return this.getAllTaskNpcs().filter((npc) => npc.category === category);
		}
		static getTaskNpcCategories() {
			const categories = new Set();
			this.getAllTaskNpcs().forEach((npc) => categories.add(npc.category));
			return Array.from(categories);
		}
		static getTaskNpcsWithLocation() {
			return this.getAllTaskNpcs().filter((npc) => npc.hasMapLocation());
		}
		static getTaskNpcsByLocation(x, y) {
			return this.getAllTaskNpcs().filter((npc) => {
				if (!npc.mapLocation) return false;
				return npc.mapLocation.x === x && npc.mapLocation.y === y;
			});
		}
		static getTaskNpcNames() {
			return this.getAllTaskNpcs().map((npc) => npc.name);
		}
	};
	var MessageBoardModule = class extends BaseModule {
		_container() {
			return $("#" + this.containerId);
		}
		constructor(credential) {
			super(credential);
			this.containerId = "_MessageBoardModule_" + RandomUtils.nextObjectID();
			this.npc = NpcProfileLoader.getRandomProfile();
		}
		async generateHTML() {
			const parts = [];
			parts.push("<section id='" + this.containerId + "' class='d-flex flex-column-reverse flex-md-row gap-2 p-2 rounded'>");
			parts.push("<article class='C_MBM_board flex-grow-1 bg-dark text-white rounded px-3 py-2' style='min-height: 64px;'>");
			parts.push("</article>");
			parts.push("<aside class='C_MBM_npc flex-shrink-0 text-center text-md-start'>");
			parts.push(`<img src='${await this.npc.getImageUrl()}' alt='${this.npc.name}' class='rounded' style='cursor:pointer' width='64' height='64'>`);
			parts.push("</aside>");
			parts.push("</section>");
			return parts.join("");
		}
		bindButtons() {
			const $container = this._container();
			MessageBoardAppender.addTarget(this.containerId, $container.find(".C_MBM_board"));
			$container.on("click", ".C_MBM_npc img", () => this.reset());
		}
		reset() {
			let html = "<span class='fw-bold text-warning'>";
			html += this.npc.getRandomGreeting();
			html += "</span>";
			this._container().find(".C_MBM_board").html(html);
		}
		async dispose() {
			MessageBoardAppender.removeTarget(this.containerId);
		}
	};
	var NotificationUtils = class NotificationUtils {
		static async send(title, options) {
			if (typeof GM_notification === "undefined") return;
			let image = options?.image;
			if (image && image.startsWith("blob:")) image = await NotificationUtils._blobToDataUrl(image);
			GM_notification({
				title,
				text: options?.body || title,
				image,
				timeout: options?.timeout ?? PocketConfigLoader.application.notificationTimeout
			});
		}
		static async _blobToDataUrl(url) {
			try {
				const blob = await (await fetch(url)).blob();
				return await new Promise((resolve, reject) => {
					const reader = new FileReader();
					reader.onload = () => resolve(reader.result);
					reader.onerror = () => reject(reader.error);
					reader.readAsDataURL(blob);
				});
			} catch (e) {
				return url;
			}
		}
	};
	var RoleNotificationService = class extends BaseRoleService {
		constructor(credential) {
			super(credential);
		}
		async send(title, options = {}) {
			if (!SetupLoader.isNotificationEnabled()) return;
			const image = await new RoleAvatarLoader(this.roleId).getImageUrl();
			await NotificationUtils.send(title, {
				body: options.message,
				image,
				timeout: options.timeout
			});
		}
	};
