	var TaskGuide = class {};
	var TaskGuideStorage = class {
		static async load(id) {
			const db = await DatabaseConnectionManager.getConnection();
			return new Promise((resolve, reject) => {
				const request = db.transaction(["TaskGuide"], "readonly").objectStore("TaskGuide").get(id);
				request.onerror = reject;
				request.onsuccess = () => {
					let data = null;
					if (request.result) {
						data = new TaskGuide();
						data.id = request.result.id;
						data.task = request.result.task;
						data.createTime = request.result.createTime;
					}
					resolve(data);
				};
			});
		}
		static async insert(data) {
			const db = await DatabaseConnectionManager.getConnection();
			const document = {};
			if (data.id) document.id = data.id;
			if (data.task) document.task = data.task;
			document.createTime = Date.now();
			return new Promise((resolve, reject) => {
				const request = db.transaction(["TaskGuide"], "readwrite").objectStore("TaskGuide").put(document);
				request.onerror = reject;
				request.onsuccess = () => resolve();
			});
		}
		static async delete(id) {
			const db = await DatabaseConnectionManager.getConnection();
			return new Promise((resolve, reject) => {
				const request = db.transaction(["TaskGuide"], "readwrite").objectStore("TaskGuide").delete(id);
				request.onerror = reject;
				request.onsuccess = () => resolve();
			});
		}
	};
	var TaskGuideService = class extends BaseCredentialService {
		constructor(credential) {
			super(credential);
		}
		async setTask(task) {
			const data = new TaskGuide();
			data.id = this.credential.id;
			data.task = task;
			await TaskGuideStorage.insert(data);
		}
		async finishTask() {
			await TaskGuideStorage.delete(this.credential.id);
		}
		async currentTask() {
			let task = null;
			const data = await TaskGuideStorage.load(this.credential.id);
			data && data.task && (task = data.task);
			return task;
		}
	};
