	var TaskGuildLoader = class {
		static getTaskData(taskName) {
			const task = task_guilds_default[taskName];
			if (!task) return null;
			return {
				walkthrough: task.walkthrough.map((line) => `<li>${line}</li>`).join(""),
				characters: task.characters || [],
				markers: task.markers
			};
		}
		static getAllNpcLocations() {
			const locationMap = new Map();
			for (const taskName in task_guilds_default) {
				const task = task_guilds_default[taskName];
				for (const marker of task.markers) {
					if (marker.npc === "岳") continue;
					const key = `${marker.x},${marker.y}`;
					if (locationMap.has(key)) {
						const location = locationMap.get(key);
						if (!location.npcNames.includes(marker.npc)) location.npcNames.push(marker.npc);
					} else locationMap.set(key, {
						x: marker.x,
						y: marker.y,
						npcNames: [marker.npc]
					});
				}
			}
			return locationMap;
		}
		static getNpcListAt(x, y) {
			const key = `${x},${y}`;
			const location = this.getAllNpcLocations().get(key);
			return location ? location.npcNames : [];
		}
		static getAllTaskNames() {
			return Object.keys(task_guilds_default);
		}
	};
	var CountdownManager = class CountdownManager {
		static execute(timeoutInMillis, handler) {
			const progressModal = ModalStackManager.getInstance().getTopModalInstance();
			const hasProgressModal = progressModal instanceof ProgressModal;
			let count = timeoutInMillis / 1e3;
			if (hasProgressModal) progressModal.prepareCountdown(count);
			PocketEventBus.emit(EventTypes.TIMEOUT_START, count);
			const timer = setInterval(() => {
				const v = Math.max(count--, 0);
				PocketEventBus.emit(EventTypes.TIMEOUT_UPDATE, v);
				if (hasProgressModal) progressModal.updateCountdown(v);
			}, 1e3);
			setTimeout(() => {
				clearInterval(timer);
				PocketEventBus.emit(EventTypes.TIMEOUT_END);
				if (hasProgressModal) progressModal.hideCountdown();
				handler();
			}, timeoutInMillis);
		}
		static wait(timeoutInMillis) {
			return new Promise((resolve) => {
				CountdownManager.execute(timeoutInMillis, resolve);
			});
		}
	};
