		async _renderTask1(metroPage) {
			$(".C_task1Button").off("click");
			const container = $("#task1Container");
			container.find("> td:first").html("");
			container.hide();
			const x = metroPage.coordinate.x;
			const y = metroPage.coordinate.y;
			if (!(x === 8 && y === 9)) return;
			container.show();
			container.find("> td:first").html(await NpcProfileLoader.getTaskNpcByName("白雪公主").getImageHtml() + "<span> </span><button role='button' class='C_task1Button' id='task1Button'>向白雪公主询问齐心丹</button>");
			if (this.sevenHeartTaskProgress.isFinished(1)) {
				PageUtils.disableElement("task1Button");
				container.hide();
			}
			$("#task1Button").on("click", async () => {
				PageUtils.disableElement("task1Button");
				const r1 = this.credential.asRequest();
				r1.set("mode", "MAP_VISIT");
				await PostClient.post("map.cgi", r1);
				const r2 = this.credential.asRequest();
				r2.set("select", "baixuegongzhu");
				r2.set("mode", "NPC_ASK");
				await PostClient.post("map.cgi", r2);
				const r3 = this.credential.asRequest();
				r3.set("npc", "baixuegongzhu");
				r3.set("mode", "NPC_ANSWER");
				r3.set("ask", "-1#3#齐心丹#");
				await PostClient.post("map.cgi", r3);
				logger$66.info("<span style='font-weight:bold;color:yellow'>白雪公主要求你帮她把匹诺曹抓来。</span>");
				this.sevenHeartTaskProgress.finish(1);
				logger$66.info("完成了第1个任务。");
				await this.refresh();
			});
		}
		async _renderTask2(metroPage) {
			$(".C_task2Button").off("click");
			const container = $("#task2Container");
			container.find("> td:first").html("");
			container.hide();
			const x = metroPage.coordinate.x;
			const y = metroPage.coordinate.y;
			if (x === 10 && y === 10) return;
			container.show();
			const avatarUrl = await new RoleAvatarLoader(this.credential.id).getImageUrl();
			container.find("> td:first").html(`<img src="${avatarUrl}" alt="" class="rounded" width="64" height="64"><span> </span><button role='button' class='C_task2Button' id='task2Button'>移动到匹诺曹处</button>`);
			if (this.sevenHeartTaskProgress.isFinished(2)) {
				PageUtils.disableElement("task2Button");
				container.hide();
			}
			if (!this.sevenHeartTaskProgress.isFinished(1)) {
				PageUtils.disableElement("task2Button");
				container.hide();
			}
			$("#task2Button").on("click", async () => {
				PageUtils.disableElement("task2Button");
				$("#taskMessage").html("<span style='color:red;font-weight:bold;font-size:200%'>移动中，请稍后。</span>");
				const plan = new TravelPlan(this.credential);
				plan.scope = metroPage.scope;
				plan.mode = metroPage.mode;
				plan.source = metroPage.coordinate;
				plan.destination = new Coordinate(10, 10);
				const movement = new TravelPlanMovement(plan, "METRO");
				await movement.move();
				movement.dispose();
				await new TownEntranceService(this.credential).changeAccessPoint();
				this.sevenHeartTaskProgress.finish(2);
				logger$66.info("完成了第2个任务。");
				await this.refresh();
			});
		}
		async _renderTask3(metroPage) {
			$(".C_task3Button").off("click");
			const container = $("#task3Container");
			container.find("> td:first").html("");
			container.hide();
			const x = metroPage.coordinate.x;
			const y = metroPage.coordinate.y;
			if (!(x === 10 && y === 10)) return;
			container.show();
			container.find("> td:first").html(await NpcProfileLoader.getTaskNpcByName("匹诺曹").getImageHtml() + "<span> </span><button role='button' class='C_task3Button' id='task3Button'>和匹诺曹战斗！</button>");
			if (this.sevenHeartTaskProgress.isFinished(3)) {
				PageUtils.disableElement("task3Button");
				container.hide();
			}
			if (!this.sevenHeartTaskProgress.isFinished(2)) {
				PageUtils.disableElement("task3Button");
				container.hide();
			}
			$("#task3Button").on("click", async () => {
				PageUtils.disableElement("task3Button");
				const p = await this.loaders.metroDashboardLoader.reload();
				Assertions.notNull(p);
				if (p.timeoutInSeconds !== void 0 && p.timeoutInSeconds > 0) {
					await this.refresh();
					return;
				}
				const r1 = this.credential.asRequest();
				r1.set("mode", "MAP_VISIT");
				await PostClient.post("map.cgi", r1);
				const battleRequest = this.credential.asRequest();
				battleRequest.set("select", "pinuocao");
				battleRequest.set("mode", "NPC_BATTLE");
				const battleResponse = await PostClient.post("map.cgi", battleRequest);
				if (battleResponse.asHtml().includes("将 怪物 全灭！")) {
					logger$66.info("<span style='font-weight:bold;color:yellow'>恭喜，你战胜了匹诺曹！</span>");
					this.sevenHeartTaskProgress.finish(3);
					logger$66.info("完成了第3个任务。");
				} else if (battleResponse.asHtml().includes("哼，比鼻子，你还不是个")) logger$66.info("<span style='font-weight:bold;color:yellow'>可悲的是，你貌似被匹诺曹按在地上摩擦！</span>");
				this.loaders.roleLoader.reset();
				await this.refresh();
			});
		}
