				skill.code = StringUtils.substringBetween(s, "(", ")");
				skill.rankHTML = $tr.children("td").eq(1).html();
				s = $tr.children("td").eq(2).text();
				const s1 = StringUtils.substringBefore(s, "/");
				const s2 = StringUtils.substringAfter(s, "/");
				skill.level = parseInt(StringUtils.substringAfter(s1, "等级:"), 10);
				skill.experience = parseInt(StringUtils.substringAfter(s2, "经验:"), 10);
				skills.push(skill);
