	var NationInformationPageParser = class NationInformationPageParser {
		static async parsePage(html) {
			const $document = PageUtils.parseHtml(html);
			const page = new NationInformationPage();
			await NationInformationPageParser._parseEvents($document, page);
			await NationInformationPageParser._parseCountries($document, page);
			return page;
		}
		static async _parseEvents($document, page) {
			const $td = $document.find("th:contains('最近发生的事件')").filter((_idx, e) => {
				return $(e).text() === "最近发生的事件";
			}).closest("table").find("> tbody:first > tr:eq(1) > td:first");
			$td.find("font:contains('●')").filter((_idx, e) => {
				return $(e).text() === "●";
			}).remove();
			const events = [];
			$td.html().split("<br>").filter((it) => it.endsWith(")")).map((it) => {
				if (it.startsWith("\n")) return it.substring(1);
				else return it;
			}).forEach((it) => events.push(it));
			page.events = [];
			for (const event of events) page.events.push(await EventHandler.processEvent(event));
		}
		static async _parseCountries($document, page) {
			page.countries = new Map();
			const ths = $document.find("center table:first").find("th[colspan='3']").toArray();
			for (const th of ths) {
				const $th = $(th);
				const $font = $th.find("> font:first");
				if ($font.length === 0) continue;
				const name = $font.text();
				const color = $font.attr("color");
				const bgcolor = $th.attr("bgcolor");
				const $tr = $th.parent().next();
				const src = $tr.find("th img:first").attr("src");
				const url = UrlNormalizer.normalizeImageUrl(src);
				const imageId = ImageCacheHelper.getImageId(url);
				let s = $tr.find("> th:eq(1)").text();
				const gold = parseInt(StringUtils.substringBefore(s, " Gold"), 10);
				const rank = StringUtils.substringBetween(s, "(", ")");
				const war = $tr.find("> th:eq(2)").text() === "参加";
				const country = new Country();
				country.name = name;
				country.color = color;
				country.bgcolor = bgcolor;
				country.imageId = imageId;
				country.gold = gold;
				country.rank = rank;
				country.war = war;
				page.countries.set(name, country);
			}
		}
	};
