			const armors = itemPage.personalEquipments.filter((it) => it.isArmor());
			const accessories = itemPage.personalEquipments.filter((it) => it.isAccessory());
			if (weapons.length !== 1 || armors.length !== 1 || accessories.length !== 1) {
				this.logger.warn("背包中武器、防具、饰品不是各一件，未能自动穿上，请手动装备。");
				return;
			}
			const set = new EquipmentSet();
			set.mode = "BY_ID";
			set.weapon.id = weapons[0].itemId;
			set.armor.id = armors[0].itemId;
			set.accessory.id = accessories[0].itemId;
			await new EquipmentSetLoader(this.credential()).load(set, itemLoader);
			itemLoader.reset();
			itemPage = await itemLoader.loadPage();
			const usingWeapon = itemPage.findUsingWeapon();
			const usingArmor = itemPage.findUsingArmor();
			const usingAccessory = itemPage.findUsingAccessory();
			this.logger.info(`当前武器：${usingWeapon !== null ? `【${usingWeapon.fullName()}】` : "无"}`);
			this.logger.info(`当前防具：${usingArmor !== null ? `【${usingArmor.fullName()}】` : "无"}`);
