	var SpellSwitchHandler = class extends BaseSpellModuleHandler {
		constructor(module) {
			super(module);
		}
		async handleClick(event) {
			const $card = $(event.currentTarget);
			const spellId = $card.attr("data-spell-id");
			const using = $card.attr("data-using") === "true";
			const spellPage = await this.module.spellLoader.loadPage();
			const targetSpellId = using ? "000" : spellId;
			const spell = spellPage.findBySpellId(targetSpellId);
			if (spell === null) {
				await ConfirmModal.alert("找不到指定的技能，忽略！");
				return;
			}
			const modal = new ProgressModal(this.credential().id, "设置技能");
			await modal.open();
			try {
				if (using) this.logger.info("正在取消技能设置...");
				else this.logger.info(`正在设置技能【${spell.name}】...`);
				if (await new PersonalSpellService(this.credential(), this.module.getTownId()).set(targetSpellId)) {
					if (using) this.logger.info("已取消技能设置。");
					else this.logger.info(`已设置技能【${spell.name}】。`);
				} else if (using) this.logger.warn("取消技能设置失败。");
				else this.logger.warn(`技能【${spell.name ?? spell.id}】设置失败，请手动设置。`);
				this.module.loaders.roleLoader.reset();
				const spellLoader = this.module.spellLoader;
				await this.module.reload({ spellLoader });
				await this.module.render();
				await this.module.triggerRefresh();
			} finally {
				await modal.close();
			}
		}
	};
