				html += `<td>${TeamItemListModal._usingHtml(item)}</td>`;
				html += `<td class='text-start'>${TeamItemListModal._fullName(item)}</td>`;
				html += `<td>${item.category}</td>`;
				html += `<td>${item.effect}</td>`;
				html += `<td>${item.weight}</td>`;
				html += `<td>${TeamItemListModal._endureHtml(item)}</td>`;
				html += `<td>${TeamItemListModal._additionalHtml(item.additionalPower)}</td>`;
				html += `<td>${TeamItemListModal._additionalHtml(item.additionalWeight)}</td>`;
				html += `<td>${TeamItemListModal._additionalHtml(item.additionalLuck)}</td>`;
				html += `<td>${TeamItemListModal._experienceHtml(item)}</td>`;
