	var PetEvolutionEvolveHandler = class extends BasePetEvolutionModuleHandler {
		constructor(module) {
			super(module);
		}
		async handleClick(event) {
			const $btn = $(event.currentTarget);
			const index = parseInt($btn.attr("data-index"), 10);
			const evolution = parseInt($btn.attr("data-evolution"), 10);
			const pet = (await this.module.petEvolutionLoader.loadPage()).evolutionPets.find((it) => it.index === index && it.evolution === evolution);
			if (!await ConfirmModal.confirm("请确认将\"" + pet.name + "\"进化到\"" + pet.afterRace + "\"？")) return;
			const modal = new ProgressModal(this.credential().id);
			await modal.open();
			try {
				this.logger.info("正在进化\"" + pet.name + "\"......");
				if (await new PersonalPetEvolutionService(this.credential()).evolve(index, evolution)) this.logger.info("进化完成。");
				else this.logger.warn("进化失败。");
				await this.module.reload();
				await this.module.render();
				await this.module.triggerRefresh();
			} finally {
				await modal.close();
			}
		}
	};
