			parts.push("<div class='card-body py-2 px-2 text-center'>");
			parts.push(`<div class='text-success fw-bold fs-5'>${petEggRate}%</div>`);
			parts.push("<div class='text-secondary small'>宠物蛋占比</div>");
			parts.push("</div>");
			parts.push("</div>");
			parts.push("</div>");
			parts.push("<div class='col'>");
			parts.push("<div class='card border-warning'>");
			parts.push("<div class='card-body py-2 px-2 text-center'>");
			parts.push(`<div class='text-warning fw-bold fs-5'>${NumberUtils.formatGold(totalGold)}</div>`);
			parts.push("<div class='text-secondary small'>累计金币</div>");
