			parts.push("<li class='nav-item' role='presentation'>");
			parts.push("<button class='nav-link small py-1 px-3 px-md-2 active' id='_town_tab_town_btn' data-tab='town' type='button' role='tab' title='城市' style='" + tabStyle + "'>");
