		async _loadBattleRecord() {
			const record = await BattleRecordStorage.load(this.credential.id);
			if (record === null) return void 0;
			if (record.createTime !== void 0) {
				if (Date.now() - record.createTime > 6e5) return;
			}
			return record;
		}
