			const $battleMenuSelect = $battleForm.find("select[name='level']");
			const battleMenuOptions = [];
			$battleMenuSelect.find("option").each((_idx, element) => {
				const $option = $(element);
				const value = $option.attr("value") ?? "";
				const text = $option.text().trim();
				battleMenuOptions.push({
					value,
					text
				});
			});
			page.battleMenuOptions = battleMenuOptions;
			page.battleCount = parseInt($battleForm.find("input:hidden[name='ktotal']").val(), 10);
			page.battleCountryId = $battleForm.find("input:hidden[name='conid']").val();
			page.battleSessionId = $battleForm.find("input:hidden[name='sessionid']").val();
