	var VipInformationPage = class {};
	var VipInformation = class {};
	var VipInformationPageParser = class {
		static parse(pageHTML) {
			const $document = PageUtils.parseHtml(pageHTML);
			const informationList = [];
			$document.find("div table:first").find("img").each((_idx, e) => {
				const information = new VipInformation();
				const img = $(e);
				let s = img.attr("src");
				information.image = StringUtils.substringAfterLast(s, "/");
				s = img.closest("td").text();
				let t = StringUtils.substringAfterLast(s, "(");
				t = "(" + t;
				information.race = StringUtils.substringBefore(s, t);
				information.code = parseInt(StringUtils.substringBetween(t, "(", ")"), 10);
				informationList.push(information);
			});
			const page = new VipInformationPage();
			page.informationList = informationList.sort((a, b) => {
				return a.code - b.code;
			});
			return page;
		}
	};
	var VipInformationPageProcessor = class extends StatelessPageProcessor {
		async process() {
			this.page = VipInformationPageParser.parse(PageUtils.currentPageHtml());
			if (!this.page.informationList || this.page.informationList.length === 0) return;
			this.#buildGroupMap();
			this.#generateHTML();
			await this.#renderGroups();
		}
		#buildGroupMap() {
			this.groupMap = new Map();
			this.page.informationList.forEach((it) => {
				const sequence = Math.floor(it.code / 1e3);
				if (!this.groupMap.has(sequence)) this.groupMap.set(sequence, []);
				this.groupMap.get(sequence).push(it);
			});
		}
		#generateHTML() {
			const groupSections = Array.from(this.groupMap.keys()).map((seq) => `
            <section class='bg-beige rounded p-2' id='vipGroup_${seq}'>
                <div class='fw-bold text-primary mb-2'>
                    <i class='bi bi-image me-1'></i>VIP ${seq} 头像
                </div>
                <div class='d-flex flex-wrap justify-content-start gap-1' id='vipGrid_${seq}'></div>
            </section>
        `).join("");
			$("body:first").html(`
            <main class='vstack gap-1 p-1 bg-secondary rounded' style='font-size:14px'>
                <section class='bg-beige rounded'>
                    <div class='p-2 rounded bg-navy text-yellowgreen'>
                        <div class='d-flex align-items-center justify-content-center'>
                            <h5 class='mb-0 fw-bold'>
                                <i class='bi bi-person-badge me-2'></i>VIP 头 像 一 览
                            </h5>
                        </div>
                    </div>
                </section>
                ${groupSections}
            </main>
        `);
		}
		async #renderGroups() {
			for (const [sequence, list] of this.groupMap) await this.#renderVipGroup(sequence, list);
		}
		async #renderVipGroup(sequence, list) {
			const grid = $(`#vipGrid_${sequence}`);
			for (const info of list) {
				const src = PocketConfigLoader.application.domain + "/image/head/" + info.image;
				const url = await ImageCacheHelper.getImageUrl(src);
				grid.append(`
                <div class='text-center' style='width:64px'>
                    <img src='${url}' alt='${info.code}' title='${info.race}'
                         class='rounded' style='width:64px;height:64px'>
                    <div class='small fw-bold' style='background-color:#CCCCCC'>${info.code}</div>
                </div>
            `);
			}
		}
	};
